def can_combine(element1, element2):
    # Normalize inputs to ensure they are within 1-14
    e1, e2 = element1, element2

    # Rule 1: Elements 1 through 5 can only be combined with themselves or with element 5
    if 1 <= e1 <= 5 and 1 <= e2 <= 5:
        if e1 == e2 or e1 == 5 or e2 == 5:
            return True
        return False

    # Rule 2: Element 6 can only be combined with element 7
    if (e1 == 6 and e2 == 7) or (e1 == 7 and e2 == 6):
        return True
    if e1 == 6 or e2 == 6:
        return False

    # Rule 3: Element 8 can be combined with any element numbered less than 14
    # Resulting element is (8 + x) % 14, with 0 treated as 14.
    # This rule implies that 8 can combine with any x in [1, 13].
    if e1 == 8 and 1 <= e2 <= 13:
        return True
    if e2 == 8 and 1 <= e1 <= 13:
        return True
    if e1 == 8 or e2 == 8:
        return False

    # No other combinations are permitted
    return False
```

