def encrypt_and_write_text(text: str, abspath: str, encoding: str = "utf-8", key: int = 1) -> int:
    def shift_char(c: str, key: int) -> str:
        if not c.isalpha():
            return c
        base = ord('A') if c.isupper() else ord('a')
        offset = ord(c) - base
        shifted = (offset + key) % 26
        return chr(base + shifted)

    words = text.split(' ')
    encrypted_words = []
    for word in words:
        encrypted_chars = [shift_char(c, key) for c in word]
        encrypted_words.append(''.join(encrypted_chars))
    encrypted_text = ' '.join(encrypted_words)

    byte_data = encrypted_text.encode(encoding)
    with open(abspath, 'wb') as f:
        f.write(byte_data)
    return len(byte_data)
```

