def fibonacci(n):
    if n < 0:
        raise ValueError("Input must be a non-negative integer.")

    memo = {}

    def fib(k):
        if k in memo:
            return memo[k]
        if k == 0:
            result = 0
        elif k == 1:
            result = 1
        else:
            result = fib(k - 1) + fib(k - 2)
        memo[k] = result
        return result

    return fib(n)
```

