import random

def has_kk_submatrix(auditorium, n, k, gender):
    """
    Checks if there exists a K*K sub-matrix in the auditorium filled entirely with the specified gender.

    Parameters:
    auditorium (list of list of str): 2D grid representing the seating arrangement.
    n (int): Size of the auditorium (N x N).
    k (int): Size of the sub-matrix to check.
    gender (str): Required gender ('M' or 'F').

    Returns:
    bool: True if such a sub-matrix exists, False otherwise.
    """
    if k > n:
        return False

    # Ensure the auditorium is square and of size n x n
    if len(auditorium) != n or any(len(row) != n for row in auditorium):
        raise ValueError("Auditorium must be an n x n grid.")

    for i in range(n - k + 1):
        for j in range(n - k + 1):
            is_valid = True
            for r in range(i, i + k):
                for c in range(j, j + k):
                    if auditorium[r][c] != gender:
                        is_valid = False
                        break
                if not is_valid:
                    break
            if is_valid:
                return True
    return False
