def are_amicable_with_prime_divisors(a, b):
    def sum_prime_divisors(n):
        if n <= 1:
            return 0
        result = 0
        d = 2
        temp = n
        while d * d <= temp:
            if temp % d == 0:
                result += d
                while temp % d == 0:
                    temp //= d
            d += 1 if d == 2 else 2  # skip even numbers after 2
        if temp > 1:
            result += temp
        return result

    sum_a = sum_prime_divisors(a)
    sum_b = sum_prime_divisors(b)

    return sum_a == b and sum_b == a
