def find_longest_palindrome(input_string: str) -> str:
    if not input_string:
        return ""

    start, end = 0, 0

    def expand_around_center(left: int, right: int) -> tuple[int, int]:
        while left >= 0 and right < len(input_string) and input_string[left] == input_string[right]:
            left -= 1
            right += 1
        # Contract one step to get the valid palindrome bounds
        return left + 1, right - 1

    for i in range(len(input_string)):
        # Odd length palindromes
        l1, r1 = expand_around_center(i, i)
        # Even length palindromes
        l2, r2 = expand_around_center(i, i + 1)

        if r1 - l1 > end - start:
            start, end = l1, r1
        elif r1 - l1 == end - start and l1 < start:
            start, end = l1, r1

        if r2 - l2 > end - start:
            start, end = l2, r2
        elif r2 - l2 == end - start and l2 < start:
            start, end = l2, r2

    return input_string[start:end + 1]
```

