def lcs_length(s1: str, s2: str) -> int:
    def helper(i: int, j: int) -> int:
        # Base case: if either index is out of bounds, LCS length is 0
        if i == len(s1) or j == len(s2):
            return 0

        # If characters match, include this character and move both indices
        if s1[i] == s2[j]:
            return 1 + helper(i + 1, j + 1)
        else:
            # If they don't match, explore both possibilities:
            # 1. Skip character from s1
            # 2. Skip character from s2
            return max(helper(i + 1, j), helper(i, j + 1))

    return helper(0, 0)
```

