import json

def extract_values(json_str, target_key):
    """
    Parses a JSON string and extracts all values associated with the target key,
    including those nested within dictionaries.

    Args:
        json_str (str): A valid JSON string.
        target_key (str): The key to search for.

    Returns:
        list: A list of values found for the target key.
    """
    result = []

    def search(obj):
        if isinstance(obj, dict):
            for k, v in obj.items():
                if k == target_key:
                    result.append(v)
                search(v)
        elif isinstance(obj, list):
            for item in obj:
                search(item)

    try:
        data = json.loads(json_str)
        search(data)
    except json.JSONDecodeError:
        return []

    return result
```

