def has_path(start_page, end_page, graph):
    if start_page == end_page:
        return True

    visited = set()
    stack = [start_page]

    while stack:
        current = stack.pop()
        if current in visited:
            continue
        visited.add(current)

        if current == end_page:
            return True

        for neighbor in graph.get(current, []):
            if neighbor not in visited:
                stack.append(neighbor)

    return False
