def sanitize_html(html):
    result = []
    i = 0
    n = len(html)

    while i < n:
        # Check for opening <script> tag (case-insensitive)
        if html[i:i+8].lower() == '<script':
            # Find the matching </script> tag
            start = i
            i += 8  # skip '<script'
            if i < n and html[i] == '>':
                i += 1  # skip '>'
                depth = 1
                while i < n and depth > 0:
                    if html[i:i+9].lower() == '</script':
                        if i + 9 < n and html[i+9] == '>':
                            depth -= 1
                            if depth == 0:
                                i += 10  # skip '</script>'
                                break
                            else:
                                i += 1
                        else:
                            i += 1
                    elif html[i] == '<':
                        # Check for nested <script> tags (treat as text inside script)
                        # We just skip until we find the closing tag
                        i += 1
                    else:
                        i += 1
                continue
            else:
                # Malformed: no closing tag or missing '>', treat rest as safe text
                result.append(html[start:])
                break
        else:
            result.append(html[i])
            i += 1

