def bstFromPreorder(preorder):
    if not preorder:
        return None

    index = [0]  # use list to allow modification inside nested function

    def build(lower, upper):
        if index[0] == len(preorder):
            return None
        val = preorder[index[0]]
        if val < lower or val > upper:
            return None
        node = TreeNode(val)
        index[0] += 1
        node.left = build(lower, val - 1)
        node.right = build(val + 1, upper)
        return node

    return build(float('-inf'), float('inf'))
