def compress_whitespace(text):
    if not text:
        return text

    result = []
    i = 0
    n = len(text)

    while i < n:
        if text[i].isspace():
            # Identify the type of whitespace (space, tab, newline, etc.)
            first_ws = text[i]
            # Skip all consecutive whitespace characters of any type
            while i < n and text[i].isspace():
                i += 1
            # Append only the first whitespace character of the sequence
            result.append(first_ws)
        else:
            result.append(text[i])
            i += 1

    return ''.join(result)
