    ]

    def convert_under_thousand(n: int) -> str:
        if n == 0:
            return ""
        elif n < 20:
            return ones[n]
        elif n < 100:
            ten = tens[n // 10]
            unit = ones[n % 10]
            return ten + (" " + unit if unit else "")
        else:
            hundred = ones[n // 100]
            rest = convert_under_thousand(n % 100)
            return hundred + " hundred" + (" " + rest if rest else "")

    parts = []
    scale_index = 0

    while num > 0:
        chunk = num % 1000
        if chunk != 0:
            chunk_words = convert_under_thousand(chunk)
            if scale_index > 0:
                chunk_words += " " + scales[scale_index]
            parts.append(chunk_words)
        num //= 1000
        scale_index += 1

    return " ".join(reversed(parts))
