def min_operations(s1: str, s2: str) -> int:
    def helper(i: int, j: int) -> int:
        # Base case: if one string is exhausted, insert/delete remaining characters
        if i == len(s1):
            return len(s2) - j
        if j == len(s2):
            return len(s1) - i

        # If characters match, move to next
        if s1[i] == s2[j]:
            return helper(i + 1, j + 1)

        # Try all three operations and take the minimum
        insert_cost = 1 + helper(i, j + 1)          # Insert s2[j]
        delete_cost = 1 + helper(i + 1, j)          # Delete s1[i]
        substitute_cost = 1 + helper(i + 1, j + 1)  # Substitute s1[i] with s2[j]

        return min(insert_cost, delete_cost, substitute_cost)

    return helper(0, 0)
```

