def process_dna_sequence(dna_sequence, reverse, complement):
    # Define complement mapping without using a dictionary
    def get_complement(nucleotide):
        if nucleotide == 'A':
            return 'T'
        elif nucleotide == 'T':
            return 'A'
        elif nucleotide == 'C':
            return 'G'
        elif nucleotide == 'G':
            return 'C'
        else:
