            return nucleotide

    # Build complemented sequence if needed
    if complement:
        result = []
        for nucleotide in dna_sequence:
            result.append(get_complement(nucleotide))
        dna_sequence = ''.join(result)

    # Reverse the sequence if needed
    if reverse:
        # Reverse without using built-in string reverse methods
        reversed_chars = []
        i = len(dna_sequence) - 1
