def log_execution(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        arg_info = []
        for arg in args:
            arg_info.append(f"{arg} ({type(arg).__name__})")
        for key, value in kwargs.items():
            arg_info.append(f"{key}={value} ({type(value).__name__})")

        print(f"Starting {func.__name__} with arguments " + ", ".join(arg_info))

        result = func(*args, **kwargs)

        print(f"Finished {func.__name__} with result {result} ({type(result).__name__})")

        return result

