def sort_workout_types(workout_types, priority_order):
    priority_map = {item: i for i, item in enumerate(priority_order)}

    # Separate known and unknown, preserving original order for unknowns
    known = []
    unknown = []

    for workout in workout_types:
        if workout in priority_map:
            known.append(workout)
        else:
            unknown.append(workout)

