def kth_permutation_sequence(N, K):
    # Helper to compute factorial using recursion
    def factorial(x):
        if x == 0 or x == 1:
            return 1
        return x * factorial(x - 1)

    # Helper to generate the K-th permutation using recursion
    def solve(n, k, available):
        if n == 0:
            return ""
        if n == 1:
            return str(available[0])

        fact = factorial(n - 1)
        index = (k - 1) // fact
        remainder = (k - 1) % fact + 1

        chosen = available[index]
        remaining = available[:index] + available[index + 1:]

        rest = solve(n - 1, remainder, remaining)
        return str(chosen) + rest

    # Generate list of numbers from 1 to N
    available = list(range(1, N + 1))
    return solve(N, K, available)
```

```python
def parse_chat_message(message):
    parts = []
    i = 0
    n = len(message)

    # Helper to extract next token (handles quoted strings)
    def get_token():
        nonlocal i
        if i >= n:
            return None

        # Skip leading spaces
        while i < n and message[i] == ' ':
            i += 1
        if i >= n:
            return None

        # Check for quoted string
        if message[i] == '"':
            i += 1  # skip opening quote
            start = i
            while i < n:
                if message[i] == '"':
                    # Check for escaped quote inside (if any) - assuming no escapes for simplicity
                    # If we encounter a quote, it ends the string
                    i += 1  # skip closing quote
                    break
                i += 1
            return message[start:i]
        else:
            # Unquoted token: read until space or end
            start = i
            while i < n and message[i] != ' ':
                i += 1
            return message[start:i]

    # 1. Command
    cmd = get_token()
    if cmd is None:
        return []
    parts.append(cmd)

    # 2. Parameters (until we see a colon for trailing message)
    while True:
        # Look ahead to see if next non-space char is ':'
        # We need to peek without consuming
        j = i
        while j < n and message[j] == ' ':
            j += 1
        if j >= n:
            break
        if message[j] == ':':
            break
        # Otherwise, it's a parameter
        param = get_token()
        if param is None:
            break
        parts.append(param)

    # 3. Trailing message (after colon)
    trailing = None
    if i < n and message[i] == ':':
        i += 1  # skip colon
        # Skip spaces after colon
        while i < n and message[i] == ' ':
            i += 1
        if i < n:
            trailing = get_token()

    if trailing is not None:
        parts.append(trailing)

    return parts

