def find_largest_prime_below(n: int) -> int:
    if n <= 2:
        return -1

    # Sieve of Eratosthenes up to n-1
    limit = n - 1
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False

    p = 2
    while p * p <= limit:
        if is_prime[p]:
            for multiple in range(p * p, limit + 1, p):
                is_prime[multiple] = False
        p += 1

    # Find the largest prime less than n
    for num in range(limit, 1, -1):
        if is_prime[num]:
            return num

    return -1
