def has_cycle(graph):
    """
    Determines if a directed graph contains a cycle.

    graph: A dictionary where keys are node indices and values are lists of adjacent nodes.
           Nodes are assumed to be 0 to N-1.

    Returns:
        bool: True if the graph contains a cycle, False otherwise.
    """
    # States: 0 = unvisited, 1 = visiting (in current DFS path), 2 = visited
    state = [0] * len(graph)

    def dfs(node):
        state[node] = 1  # Mark as visiting
        for neighbor in graph.get(node, []):
            if state[neighbor] == 1:
                # Back edge found -> cycle
                return True
            if state[neighbor] == 0:
                if dfs(neighbor):
                    return True
        state[node] = 2  # Mark as visited
        return False

    # Check all nodes in case the graph is not fully connected
    for node in range(len(graph)):
        if state[node] == 0:
            if dfs(node):
                return True
    return False
```

