def invert_mapping(mapping):
    result = {}

    def traverse(node, path):
        if not isinstance(node, dict):
            # Leaf value
            if node not in result:
                result[node] = []
            result[node].append(path)
            return

        for key, value in node.items():
            new_path = path + [key]
            traverse(value, new_path)

    traverse(mapping, [])
    return result
```

