def calculate_output_size(input_size, kernel_size, stride, padding, dilation, cover_all=False):
    def compute_dim(in_size, k_size, s, p, d, cover_all):
        effective_kernel = (k_size - 1) * d + 1
        if cover_all:
            # Adjusted formula to ensure full coverage
            out_size = ((in_size + 2 * p - effective_kernel) // s) + 1
            if out_size <= 0:
                out_size = 0
        else:
            out_size = (in_size + 2 * p - effective_kernel) // s + 1
        return out_size

    if len(input_size) != len(kernel_size) != len(stride) != len(padding) != len(dilation):
        raise ValueError("All input tuples must have the same length.")

    output_size = tuple(
        compute_dim(inp, k, s, pad, dil, cover_all)
        for inp, k, s, pad, dil in zip(input_size, kernel_size, stride, padding, dilation)
    )

    return output_size
