def merge_dictionaries(dict_a, dict_b):
    merged = {}

    # Collect all unique keys
    all_keys = set(dict_a.keys()) | set(dict_b.keys())

    for key in all_keys:
        if key in dict_a and key in dict_b:
            # If value in dict_a is 0, use dict_b's value; otherwise use dict_a's value
            if dict_a[key] == 0:
                merged[key] = dict_b[key]
            else:
                merged[key] = dict_a[key]
        elif key in dict_a:
            merged[key] = dict_a[key]
        else:
            merged[key] = dict_b[key]

    # Sort keys lexicographically and rebuild the dictionary
    sorted_keys = sorted(merged.keys())
    dict_merged = {k: merged[k] for k in sorted_keys}

    return dict_merged
