def find_most_common_elements(numbers, n):
    # Manual counting without using built-in count or Counter
    counts = {}
    for num in numbers:
        if num in counts:
            counts[num] += 1
        else:
            counts[num] = 1

    # Convert to list of (element, count) tuples
    items = []
    for key in counts:
        items.append((key, counts[key]))

    # Manual sorting by count descending, then by element descending for tie-breaking (optional)
    # We'll implement a simple selection-based approach to get top n without full sort
    if len(items) <= n:
        # Return all
        result = {}
        for key, count in items:
            result[key] = count
        return result

    # We need the top n items by count
    # Use a simple selection algorithm: find max n times
    result = {}
    remaining = items[:]  # copy

    for _ in range(n):
        # Find the item with the maximum count in remaining
        max_count = -1
        max_item = None
        for i in range(len(remaining)):
            if remaining[i][1] > max_count:
                max_count = remaining[i][1]
                max_item = remaining[i]
            elif remaining[i][1] == max_count and max_item is not None:
                # Tie-breaker: larger element value first (optional, but deterministic)
                if remaining[i][0] > max_item[0]:
                    max_item = remaining[i]

        if max_item is None:
            break

        result[max_item[0]] = max_item[1]
        # Remove the selected item from remaining
        remaining.pop(remaining.index(max_item))

    return result
```

