def prime_squares(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def count_ways(p):
        if p == 2:
            return 0
        # Count pairs (a, b) with 0 <= a <= b and a^2 + b^2 = p
        count = 0
        limit = int(p ** 0.5)
        for a in range(limit + 1):
            b2 = p - a * a
            if b2 < 0:
                break
            b = int(b2 ** 0.5)
            if b * b == b2 and a <= b:
                count += 1
        return count

    result = {}
    for num in range(2, n + 1):
        if is_prime(num):
            result[num] = count_ways(num)
    return result
