import random
import math

class PoissonDistribution:
    def __init__(self, mean):
        if mean < 0:
            raise ValueError("Mean must be non-negative")
        self._mean = float(mean)

    def setMean(self, mean):
        if mean < 0:
            raise ValueError("Mean must be non-negative")
        self._mean = float(mean)

    def generate(self):
        if self._mean <= 0:
            return 0
        # Standard Poisson generation using the inverse transform method
        L = math.exp(-self._mean)
        k = 0
        p = 1.0
        while True:
            k += 1
            p *= random.random()
            if p < L:
                return k - 1
        # Fallback (should not be reached)
        return int(2 * self._mean)

def dynamic_poisson(p, mean):
    if mean <= 0:
        return 0
    p.setMean(mean)
    result = p.generate()
    # Ensure the result does not exceed twice the current mean
    if result > 2 * mean:
        result = int(2 * mean)
    return result
