def get_all_subsidiaries(orgs, relationships):
    # Build adjacency list for parent -> children
    children = {}
    for p, c in relationships:
        children.setdefault(p, []).append(c)

    # Initialize result set with input organizations
    result = set(orgs)

    # Perform BFS/DFS to traverse up to 20 levels, avoiding cycles
    visited = set()
    queue = list(orgs)  # start from all input organizations

    # Track depth to limit to 20 levels of subsidiaries
    # We'll use a queue of (node, depth)
    queue_with_depth = [(org, 0) for org in orgs]

    while queue_with_depth:
        current_org, depth = queue_with_depth.pop(0)

        if depth > 20:
            continue

        if current_org in visited:
            continue
        visited.add(current_org)

        # Add children if not already in result
        if current_org in children:
            for child in children[current_org]:
                if child not in result:
                    result.add(child)
                # Enqueue child if not visited and depth allows
                if child not in visited and depth < 20:
                    queue_with_depth.append((child, depth + 1))

    return result
```

