                        json_sub = json_val[key]
                        yaml_sub = yaml_val[key]
                        if isinstance(json_sub, dict) and isinstance(yaml_sub, dict):
                            # Nested dict: recurse
                            count = update_recursive(json_sub, yaml_sub, count)
                        elif json_sub != yaml_sub:
                            # Leaf values differ: update
                            yaml_val[key] = json_sub
                            count += 1
            return count
        elif isinstance(json_val, dict):
            # json_val is a dict but yaml_val is not -> treat as mismatch, no update
            return count
        elif json_val != yaml_val:
            # Both are non-dict and differ: update
            yaml_val = json_val
            count += 1
        return count

    updated_count = 0
    update_recursive(config_json, config_yaml, updated_count)
    return updated_count
