def circular_binary_search(arr, target):
    """
    Perform a recursive binary search on a sorted circular list.

    The list is assumed to be sorted in ascending order when viewed linearly,
    but conceptually circular (last element connects to first).
    However, since the input is given as a linear sorted array that wraps around,
    we treat it as a standard sorted array for binary search purposes.

    If the target exists, return its index; otherwise, return -1.

    Parameters:
        arr (List[int]): Sorted list of integers (linear representation of circular list)
        target (int): The value to search for

    Returns:
        int: Index of target if found, else -1
    """
    def binary_search(left, right):
        if left > right:
            return -1

        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            return binary_search(mid + 1, right)
        else:
            return binary_search(left, mid - 1)

    return binary_search(0, len(arr) - 1)
```

