def convert_ip_address(ip: str) -> str:
    def process_section(s: str) -> str:
        if not s:
            return s
        # Check if the section is purely numeric
        if s.isdigit():
            # Remove leading zeros
            num_str = s.lstrip('0')
            if num_str == "":
                num_str = "0"
            num = int(num_str)
            if num > 255:
