def pack_binary_data(value, bits):
    if bits % 8 != 0:
        raise ValueError("bits must be a multiple of 8")

    num_bytes = bits // 8
    result = bytearray()

    for i in range(num_bytes):
        shift = (num_bytes - 1 - i) * 8
        byte_val = (value >> shift) & 0xFF
        result.append(byte_val)

    return bytes(result)
