def capitalize_titles(titles):
    articles = {"a", "an", "the"}
    conjunctions = {"and", "but", "or", "nor", "for", "yet", "so"}
    prepositions = {
        "about", "above", "after", "again", "against", "along", "among", "around",
        "at", "before", "behind", "below", "beneath", "beside", "besides", "between",
        "beyond", "by", "down", "during", "except", "excepting", "for", "from",
        "in", "inside", "into", "like", "near", "of", "off", "on", "onto", "out",
        "outside", "over", "past", "since", "than", "through", "throughout", "till",
        "to", "toward", "under", "underneath", "until", "up", "upon", "versus",
        "via", "with", "within", "without"
    }
    small_words = articles | conjunctions | prepositions

    def capitalize_word(word, index, total_words):
        word = word.strip()
        if not word:
            return word

        # First word and last word are always capitalized
        if index == 0 or index == total_words - 1:
            return word.capitalize()

        # Check if the word is a small word (article, conjunction, preposition) with < 5 letters
        if len(word) < 5 and word.lower() in small_words:
            return word.lower()

        # Otherwise, capitalize the first letter
        return word.capitalize()

    result = []
    for title in titles:
        words = title.split()
        if not words:
            result.append("")
            continue

        capitalized_words = [
            capitalize_word(word, i, len(words))
            for i, word in enumerate(words)
        ]
        result.append(" ".join(capitalized_words))

    return result
