def nth_primes(n: int) -> list[int]:
    if n <= 0:
        return []

    # Upper bound estimate using the prime number theorem:
    # p_n < n (ln n + ln ln n) for n >= 6
    if n < 6:
        upper_bound = 15
    else:
        import math
        upper_bound = int(n * (math.log(n) + math.log(math.log(n)))) + 1

    sieve = [True] * upper_bound
    sieve[0] = sieve[1] = False

    for i in range(2, int(upper_bound ** 0.5) + 1):
        if sieve[i]:
            step_start = i * i
            sieve[step_start:upper_bound:i] = [False] * ((upper_bound - 1 - step_start) // i + 1)

    primes = [i for i, is_prime in enumerate(sieve) if is_prime]
    return primes[:n]
