    opening_brackets = set(bracket_map.values())

    for char in expression:
        if char in opening_brackets:
            stack.append(char)
        elif char in bracket_map:
            if not stack:
                return False
            top = stack.pop()
            if bracket_map[char] != top:
                return False
        # Ignore all other characters

    return len(stack) == 0
```

