    is_prime[0] = is_prime[1] = False

    limit = int(n ** 0.5) + 1
    for i in range(2, limit):
        if is_prime[i]:
            # Start from i*i and mark multiples
            step = i
            start = i * i
            is_prime[start:n:step] = [False] * ((n - 1 - start) // step + 1)

    return sum(i for i, prime in enumerate(is_prime) if prime)
