def level_order_traversal(tree):
    if not tree:
        return []

    result = []
    queue = [tree]

    while queue:
        level_size = len(queue)
        current_level = []

        for _ in range(level_size):
            node = queue.pop(0)
            current_level.append(node[0])

            if node[1] is not None:
                queue.append(node[1])
            if node[2] is not None:
                queue.append(node[2])

