def calculate_median(hours):
    # Make a copy to avoid modifying the original list
    arr = hours[:]
    n = len(arr)

    if n == 0:
        return 0.0

    # Sort the list manually using a simple implementation (e.g., selection sort)
    for i in range(n):
        min_idx = i
        for j in range(i + 1, n):
            if arr[j] < arr[min_idx]:
                min_idx = j
        arr[i], arr[min_idx] = arr[min_idx], arr[i]

    if n % 2 == 1:
        median = float(arr[n // 2])
    else:
        mid1 = arr[n // 2 - 1]
        mid2 = arr[n // 2]
        median = (mid1 + mid2) / 2.0

