def find_wake_up_days(D, N, T, knocks):
    result_days = []
    for day_idx, day_knocks in enumerate(knocks, start=1):
        # Find the longest strictly increasing subsequence length
        # We need any subsequence of length > T
        # Use patience sorting / LIS O(N log N)
        tails = []  # tails[i] = smallest tail of all increasing subsequences of length i+1
        for x in day_knocks:
            # binary search for the first element >= x
            import bisect
            idx = bisect.bisect_left(tails, x)
            if idx < len(tails):
                tails[idx] = x
