def validate_input(input_data, condition_list):
    def get_nested_value(data, key_path):
        parts = key_path.split('.')
        current = data
        for part in parts:
            if isinstance(current, dict) and part in current:
                current = current[part]
            else:
                return None
        return current

    def check_condition(data, key_path, operator, value):
        val = get_nested_value(data, key_path)
        if val is None:
            return False

        if operator == '<':
            return val < value
        elif operator == '>':
            return val > value
        elif operator == '==':
            return val == value
        elif operator == '<=':
            return val <= value
        elif operator == '>=':
            return val >= value
        elif operator == '!=':
            return val != value
        else:
            return False

    for key, op, val in condition_list:
        if not check_condition(input_data, key, op, val):
            print(f"[WARNING] Check Failed: {key} {op} {val}")
            return True

    return False
