def min_deletions_to_anagram(s1, s2):
    from collections import Counter

    count1 = Counter(s1)
    count2 = Counter(s2)

    deletions = 0

    # For characters present in both strings, keep the minimum count
    common_chars = set(count1.keys()) & set(count2.keys())
    for ch in common_chars:
        keep = min(count1[ch], count2[ch])
        deletions += (count1[ch] - keep) + (count2[ch] - keep)

    # Add remaining characters from s1 that are not in s2 (or have excess)
    for ch, cnt in count1.items():
        if ch not in count2:
            deletions += cnt
        else:
            deletions += max(0, count1[ch] - count2[ch])

    # Add remaining characters from s2 that are not in s1 (or have excess)
    for ch, cnt in count2.items():
        if ch not in count1:
            deletions += cnt
        else:
            deletions += max(0, count2[ch] - count1[ch])

    return deletions
```

