import json
import re
import sys

def to_snake_case(name):
    """Convert camelCase or PascalCase to snake_case."""
    # Insert an underscore before any uppercase letter that follows a lowercase letter or digit
    s1 = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', name)
    # Insert an underscore before any uppercase letter that is followed by a lowercase letter
    # and preceded by an uppercase letter (handles consecutive capitals like "XMLParser" -> "xml_parser")
    s2 = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s1)
    return s2.lower()

def process_input_data(input_source):
    """
    Process JSON data from either a file path or a JSON string.
    Converts all keys from camelCase/PascalCase to snake_case.
    Returns the transformed JSON as a string.
    """
    try:
        data = json.loads(input_source)
    except json.JSONDecodeError as e:
        raise ValueError(f"Invalid JSON input: {e}")

    def convert_keys(obj):
        if isinstance(obj, dict):
            return {to_snake_case(k): convert_keys(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [convert_keys(item) for item in obj]
        else:
            return obj

    transformed_data = convert_keys(data)
    return json.dumps(transformed_data, indent=2)

if __name__ == "__main__":
    if len(sys.argv) > 1:
        # Check if the argument is a file or a JSON string
        try:
            with open(sys.argv[1], 'r', encoding='utf-8') as f:
                input_source = f.read()
        except FileNotFoundError:
            # If file not found, treat the argument as a JSON string
            input_source = sys.argv[1]
    else:
        # No argument provided, read from stdin
        input_source = sys.stdin.read()

    result = process_input_data(input_source)
    print(result)
```

