```python
def flatten_dict(d, parent_key='', sep='.'):
    """
    Flattens a nested dictionary into a single-level dictionary.

    Keys are constructed by concatenating keys with a separator (default '.').
    List indices are included in the key path.

    Args:
        d (dict): The nested dictionary to flatten.
        parent_key (str): The base key for the current level.
        sep (str): Separator between key levels.

    Returns:
        dict: A flattened dictionary.
    """
    items = []

    for key, value in d.items():
        new_key = f"{parent_key}{sep}{key}" if parent_key else key

        if isinstance(value, dict):
            items.extend(flatten_dict(value, new_key, sep).items())
        elif isinstance(value, list):
            for index, item in enumerate(value):
                if isinstance(item, dict):
                    items.extend(flatten_dict(item, f"{new_key}{sep}{index}", sep).items())
                else:
                    items.append((f"{new_key}{sep}{index}", item))
        else:
            items.append((new_key, value))

    return dict(items)
```

