def classify_reviews(reviews):
    positive_keywords = {
        "loved", "exceeded", "amazing", "great", "excellent", "wonderful",
        "fantastic", "perfect", "best", "happy", "satisfied", "recommend",
        "love", "like", "good", "nice", "awesome", "superb", "outstanding"
    }

    negative_keywords = {
        "terrible", "horrible", "awful", "bad", "worst", "hate", "dislike",
        "poor", "disappointing", "frustrated", "angry", "waste", "broken",
        "defective", "fail", "failed", "not buy", "would not buy"
    }

    def classify(text):
        text_lower = text.lower()
        pos_count = sum(1 for word in positive_keywords if word in text_lower)
        neg_count = sum(1 for word in negative_keywords if word in text_lower)

        if pos_count > neg_count:
            return "positive"
        elif neg_count > pos_count:
            return "negative"
        else:
            return "neutral"

    return [(review, classify(review)) for review in reviews]
