def safe_retrieve_value(data_dict, key):
    try:
        value = data_dict.get(key)
        if value is None:
            return None

        if isinstance(value, str):
            if value == '':
                return value

            # Try to convert to int first
            try:
                int_val = int(value)
                return int_val
            except ValueError:
                pass

            # Try to convert to float
            try:
                float_val = float(value)
                # If it's a whole number float, we still return float as per spec example '5.9' -> 5.9
                # But if the original string was '0', we already handled it above via int conversion
                # However, spec says: if value is '0' return integer 0. Our int conversion handles that.
                # For '123.45', float conversion is correct.
                return float_val
            except ValueError:
                pass

            # If neither int nor float conversion succeeded, return the string as is
            return value

        # If value is already an int or float, return as is
        return value

    except Exception:
        return None
