def find_largest_prime(n):
    if n <= 2:
        return None

    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        limit = int(num ** 0.5) + 1
        for i in range(3, limit, 2):
            if num % i == 0:
                return False
        return True

    # Start from n-1 and go downwards
    candidate = n - 1
    while candidate >= 2:
        if is_prime(candidate):
            return candidate
        candidate -= 1

    return None
