import functools

def log_function_call(func):
    @functools.wraps(func)
    def wrapper(*args, **kwargs):
        # Build the argument string
        parts = []
        if args:
            for i, arg in enumerate(args):
                parts.append(f"{arg}")
        if kwargs:
            for key, value in kwargs.items():
                parts.append(f"{key}={value}")

        # If there are positional args, we need to represent them as positional in the log
        # But the sample shows keyword style for all. To match sample exactly:
        # We'll reconstruct the call signature as if all were keyword arguments.
        # However, we don't have the original parameter names unless we inspect the function.
        # Since the problem expects format like multiply(x=6, y=7), we need param names.
        # We can get them from func.__code__.co_varnames and co_argcount.

        import inspect
        sig = inspect.signature(func)
        bound = sig.bind(*args, **kwargs)
        bound.apply_defaults()

        arg_strs = []
        for name, value in bound.arguments.items():
            arg_strs.append(f"{name}={value}")

        print(f"Calling {func.__name__}({', '.join(arg_strs)})")

        return func(*args, **kwargs)

    return wrapper
