def remove_consecutive_duplicates(lst):
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if not lst:
        return []

    result = [lst[0]]
    for i in range(1, len(lst)):
        current = lst[i]
        prev = lst[i - 1]
        if current == prev and is_prime(current):
            continue
        result.append(current)

    return result
