import re
from datetime import datetime

def classify_data(data):
    result = {}

    for s in data:
        # Check for boolean first (case-sensitive as per spec: 'True' or 'False')
        if s == 'True' or s == 'False':
            result[s] = 'boolean'
            continue

        # Check for date format YYYY-MM-DD
        if re.match(r'^\d{4}-\d{2}-\d{2}$', s):
            try:
                datetime.strptime(s, '%Y-%m-%d')
                result[s] = 'date'
                continue
            except ValueError:
                pass

        # Check for integer (optional leading minus, digits only)
        if re.match(r'^-?\d+$', s):
            result[s] = 'integer'
            continue

        # Check for float (optional leading minus, digits, optional decimal part)
        if re.match(r'^-?\d+(\.\d+)?$', s):
            result[s] = 'float'
            continue

        # Default to string
        result[s] = 'string'

    return result
