def find_closest_value_in_bst(root, target):
    if root is None:
        return None

    closest = root.value
    min_diff = abs(root.value - target)

    current = root
    while current is not None:
        diff = abs(current.value - target)
        if diff < min_diff:
            min_diff = diff
            closest = current.value
        elif diff == min_diff:
            # If same difference, choose the smaller value
            if current.value < closest:
                closest = current.value

