def search_insert(numbers, target):
    left, right = 0, len(numbers) - 1
    result = -1

    while left <= right:
        mid = (left + right) // 2
        if numbers[mid] >= target:
            if numbers[mid] == target:
                # Found target; move right to find the last occurrence
                result = mid
                left = mid + 1
            else:
                # numbers[mid] > target; this could be the smallest duplicate >= target
                # but we need to check if there's a later occurrence of the same value
                # or a smaller value >= target. Continue searching right.
                result = mid
                left = mid + 1
        else:
            left = mid + 1

    if result != -1:
        # We found at least one occurrence of target; now find the last occurrence
        # by scanning right from result (since we already know target exists)
        last = result
        while last + 1 < len(numbers) and numbers[last + 1] == target:
            last += 1
        return last
    else:
        # target not found; return insertion index
        return left
