def find_unique_pairs(nums, target):
    seen = set()
    pairs = set()

    for num in nums:
        complement = target - num
        if complement in seen:
            # Store the pair in sorted order to ensure uniqueness
            pair = tuple(sorted((num, complement)))
            pairs.add(pair)
        seen.add(num)

    return list(pairs)
