                val_override = override[key]
                if isinstance(val_base, list) and isinstance(val_override, list):
                    result[key] = val_base + val_override
                else:
                    result[key] = val_override
            elif key in base:
                result[key] = base[key]
            else:
                result[key] = override[key]
