def length_of_lis(nums):
    if not nums:
        return 0

    n = len(nums)
    tails = []  # tails[i] is the smallest tail of all increasing subsequences of length i+1

    for x in nums:
        # Use binary search to find the insertion point
        left, right = 0, len(tails)
        while left < right:
            mid = (left + right) // 2
            if tails[mid] < x:
                left = mid + 1
            else:
                right = mid
        # If x is greater than all tails, append it
        if left == len(tails):
            tails.append(x)
        else:
            tails[left] = x

    return len(tails)
