def shortest_path_in_maze(maze):
    if not maze or not maze[0]:
        return -1

    n = len(maze)
    m = len(maze[0])

    # Check start and end cells
    if maze[0][0] == 1 or maze[n - 1][m - 1] == 1:
        return -1

    # dp[i][j] = shortest path length to reach cell (i, j)
    # Initialize with infinity
    dp = [[float('inf')] * m for _ in range(n)]
    dp[0][0] = 0

    # Directions: right and down
    directions = [(0, 1), (1, 0)]

    for i in range(n):
        for j in range(m):
            if maze[i][j] == 1:
                continue
            if dp[i][j] == float('inf'):
                continue

            # Try moving right
            if j + 1 < m and maze[i][j + 1] == 0:
                if dp[i][j] + 1 < dp[i][j + 1]:
                    dp[i][j + 1] = dp[i][j] + 1

            # Try moving down
            if i + 1 < n and maze[i + 1][j] == 0:
                if dp[i][j] + 1 < dp[i + 1][j]:
                    dp[i + 1][j] = dp[i][j] + 1

    result = dp[n - 1][m - 1]
    return result if result != float('inf') else -1
```

