def editDistance(s1, s2):
    # Ensure s1 is the smaller string to perform operations in-place on it
    if len(s1) > len(s2):
        s1, s2 = s2, s1

    m, n = len(s1), len(s2)

    # Create a DP table with (m+1) rows and (n+1) columns
    # We will modify s1 in-place conceptually, but we need a DP table for computation
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases
    for i in range(m + 1):
        dp[i][0] = i  # Deleting all characters from s1[0:i]
    for j in range(n + 1):
        dp[0][j] = j  # Inserting all characters of s2[0:j] into empty s1

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],      # Deletion
                    dp[i][j - 1],      # Insertion
                    dp[i - 1][j - 1]   # Substitution
                )

    return dp[m][n]
```

