def create_alternating_tuple(n):
    def is_prime(num):
        if num < 2:
            return False
        if num == 2:
            return True
        if num % 2 == 0:
            return False
        for i in range(3, int(num ** 0.5) + 1, 2):
            if num % i == 0:
                return False
        return True

    def get_primes(count):
        primes = []
        num = 2
        while len(primes) < count:
            if is_prime(num):
                primes.append(num)
            num += 1
        return primes

    def get_fibonacci(count):
        fib = [0, 1]
        while len(fib) < count + 1:
            fib.append(fib[-1] + fib[-2])
        return fib

    primes = get_primes(n)
    fibs = get_fibonacci(n)

    result = []
    for i in range(n):
        result.append(primes[i])
        result.append(fibs[i])

    return tuple(result[:n])
