def isValid(ip: str) -> int:
    parts = ip.split('.')
    if len(parts) != 4:
        return 0

    for part in parts:
        if not part:
            return 0

        # Determine base and value
        if part.startswith('0x') or part.startswith('0X'):
            # Hexadecimal
            try:
                val = int(part, 16)
            except ValueError:
                return 0
            base = 16
        elif part.startswith('0') and len(part) > 1 and part[1].isdigit():
            # Octal: starts with '0' and has more digits
            # Check that all characters are valid octal digits (0-7)
            if not all(c in '01234567' for c in part):
                return 0
            try:
                val = int(part, 8)
            except ValueError:
                return 0
            base = 8
        else:
            # Decimal: no leading zero unless the number is exactly "0"
            if len(part) > 1 and part[0] == '0':
                return 0
            try:
                val = int(part, 10)
            except ValueError:
                return 0
            base = 10

        # Check range [0, 255]
        if val < 0 or val > 255:
            return 0

    return 1
