def find_node_with_char(root, target):
    if root is None:
        return None

    # Stack for DFS: each element is a node
    stack = [root]

    while stack:
        node = stack.pop()
        if node.val == target:
            return node

        # Push right first so that left is processed first (pre-order)
        if node.right:
            stack.append(node.right)
        if node.left:
            stack.append(node.left)

    return None
