def recursive_power(base, exponent):
    # Helper to convert exponent to ternary digits (list of ints, least significant first)
    def to_ternary(n):
        if n == 0:
            return []
        digits = []
        while n > 0:
            digits.append(n % 3)
            n //= 3
        return digits

    # Recursive function to compute base^exponent using ternary decomposition
    def power_with_ternary(digits, idx):
        # idx is the current position (power of 3)
        if idx == len(digits):
            return 1

        digit = digits[idx]
        # Compute base^(3^idx)
        # We can compute this recursively by repeated squaring-like logic in base 3
        # But per spec: recursively calculate the power of base for each digit
        # Interpretation: For each digit d at position idx, we need base^(d * 3^idx)
        # We'll compute base^(3^idx) once and then raise to digit power

        # Compute base^(3^idx) recursively
        def base_power_of_three(idx):
            if idx == 0:
                return base
            # base^(3^idx) = (base^(3^(idx-1)))^3
            prev = base_power_of_three(idx - 1)
            # Compute prev^3 without ** or pow
            return prev * prev * prev

        term = base_power_of_three(idx)
        if digit == 0:
            return 1
        elif digit == 1:
            return term
        elif digit == 2:
            return term * term

        # Multiply results from higher positions
        return term * power_with_ternary(digits, idx + 1)

    if exponent == 0:
        return 1
    if exponent == 1:
        return base

    ternary_digits = to_ternary(exponent)
    return power_with_ternary(ternary_digits, 0)
```

