```python
def edit_distance(str1, str2):
    m, n = len(str1), len(str2)
    # Create a DP table with (m+1) x (n+1)
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Base cases: converting empty string to str2 (insertions)
    for i in range(m + 1):
        dp[i][0] = i  # deletions from str1 to make it empty
    for j in range(n + 1):
        dp[0][j] = j  # insertions into empty string to make str2

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            if str1[i - 1] == str2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]  # no operation needed
            else:
                dp[i][j] = 1 + min(
                    dp[i - 1][j],    # deletion
                    dp[i][j - 1],    # insertion
                    dp[i - 1][j - 1] # substitution
                )

    return dp[m][n]
```

