def matrix_multiply(A, B):
    # Check if A and B are valid lists of lists
    if not isinstance(A, list) or not isinstance(B, list):
        return "Invalid matrix dimensions for multiplication."

    if len(A) == 0 or len(B) == 0:
        return "Invalid matrix dimensions for multiplication."

    # Check if all rows in A have the same length
    row_len_A = len(A[0])
    for row in A:
        if len(row) != row_len_A:
            return "Invalid matrix dimensions for multiplication."

    # Check if all rows in B have the same length
    row_len_B = len(B[0])
    for row in B:
        if len(row) != row_len_B:
            return "Invalid matrix dimensions for multiplication."

    # Check if multiplication is possible: columns of A must equal rows of B
    if row_len_A != len(B):
        return "Invalid matrix dimensions for multiplication."

    # Perform matrix multiplication
    result = []
    for i in range(len(A)):
        row_result = []
        for j in range(len(B[0])):
            sum_val = 0
            for k in range(row_len_A):
                sum_val += A[i][k] * B[k][j]
            row_result.append(sum_val)
        result.append(row_result)

    return result
```

