def min_nodes_to_delete(arr):
    if not arr:
        return 0

    # We need the longest strictly increasing subsequence (LIS)
    # The answer is n - length_of_LIS
    n = len(arr)
    if n == 1:
        return 0

    # dp[i] = length of LIS ending at index i
    dp = [1] * n
    for i in range(1, n):
        for j in range(i):
            if arr[j] < arr[i]:
                dp[i] = max(dp[i], dp[j] + 1)

    lis_length = max(dp)
    return n - lis_length
```

