def searchRange(nums, target):
    def findBound(is_left):
        left, right = 0, len(nums) - 1
        result = -1
        while left <= right:
            mid = (left + right) // 2
            if nums[mid] == target:
                result = mid
                if is_left:
                    right = mid - 1
                else:
                    left = mid + 1
            elif nums[mid] < target:
                left = mid + 1
            else:
                right = mid - 1
        return result

    start = findBound(True)
    if start == -1:
        return [-1, -1]
    end = findBound(False)
    return [start, end]
