def sort_tokens(input_string):
    if not input_string:
        return input_string

    # Determine the separator used
    if ';' in input_string:
        separator = ';'
    elif ',' in input_string:
        separator = ','
    else:
        # No separator found; treat the whole string as a single token
        return input_string

    # Split into tokens
    tokens = input_string.split(separator)

    # Sort tokens
    sorted_tokens = sorted(tokens)

    # Join back with the original separator
    return separator.join(sorted_tokens)
