def convert_to_bytes(value):
    if isinstance(value, bytes):
        return value
    elif isinstance(value, int):
        if not (0 <= value <= 255):
            raise ValueError("Integer must be in the range 0 to 255.")
        return bytes([value])
    elif isinstance(value, str):
