                    'nested_content': formatted
                })
        return result
    elif isinstance(content, str):
        return {
            'level': level,
            'content': content,
            'color': color_map[level]
        }
    else:
        # For non-string, non-dict content (e.g., numbers, None), treat as string content
        return {
            'level': level,
            'content': str(content),
