def parse_expression(expression: str):
    # Allowed characters: digits, spaces, '+', '-', '*', '/', '(', ')'
    allowed = set("0123456789 +-*()/ ")

    # Remove spaces
    expr = expression.replace(" ", "")

    # Check for invalid characters
    for ch in expr:
        if ch not in allowed:
            raise ValueError(f"Invalid character in expression: '{ch}'")

    # Check parentheses balance
    balance = 0
    for ch in expr:
        if ch == '(':
            balance += 1
        elif ch == ')':
            balance -= 1
        if balance < 0:
            raise ValueError("Unbalanced parentheses: closing parenthesis before opening")
    if balance != 0:
        raise ValueError("Unbalanced parentheses: missing closing parenthesis")

    result = []
    i = 0
    n = len(expr)

    while i < n:
        ch = expr[i]

        if ch.isdigit():
            # Parse multi-digit number (up to 3 digits as per constraint, but we'll parse all consecutive digits)
            num_str = []
            while i < n and expr[i].isdigit():
                num_str.append(expr[i])
                i += 1
            # Convert to integer
            result.append(int("".join(num_str)))
            continue

        elif ch in "+-*/()":
            result.append(ch)
            i += 1
        else:
            # Should not happen due to earlier validation
            raise ValueError(f"Unexpected character during parsing: '{ch}'")

    return result
