def find_special_palindromes(text):
    import string

    vowels = set('aeiouAEIOU')
    consonants = set(c for c in string.ascii_lowercase if c not in 'aeiou')
    consonants.update(c.upper() for c in consonants)

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        i = 3
        while i * i <= n:
            if n % i == 0:
                return False
            i += 2
        return True

    def is_palindrome(s):
        return s == s[::-1]

    def count_unique_vowels(s):
        return len(set(c for c in s if c in vowels))

    def count_unique_consonants(s):
        return len(set(c for c in s if c in consonants))

    n = len(text)
    special_lengths = set()

    # Check all substrings
    for length in range(3, n + 1):
        if not is_prime(length):
            continue

        for start in range(n - length + 1):
            end = start + length
            substring = text[start:end]

            if not is_palindrome(substring):
                continue

            if count_unique_vowels(substring) >= 3 and count_unique_consonants(substring) >= 2:
                special_lengths.add(length)

    if not special_lengths:
        return 1

    product = 1
    for length in special_lengths:
        product *= length

    return product
