def find_prime_factors(n):
    if n < 2:
        return []

    factors = []
    d = 2

    # Handle factor 2 separately
    if n % d == 0:
        factors.append(d)
        while n % d == 0:
            n //= d

    # Check odd factors from 3 upwards
    d = 3
    while d * d <= n:
        if n % d == 0:
            factors.append(d)
            while n % d == 0:
                n //= d
        d += 2

    # If n is still greater than 1, then it's a prime factor
    if n > 1:
        factors.append(n)

    return factors
