def find_repetitions(data, a_list, window_size):
    def is_prime(n: int) -> bool:
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(n ** 0.5) + 1
        for i in range(3, limit, 2):
            if n % i == 0:
                return False
        return True

    if window_size != len(a_list):
        return 0

    count = 0
    n = len(data)
    m = window_size

    # Pre-check: if a_list itself has no prime, no window can satisfy the condition
    has_prime_in_a = any(is_prime(x) for x in a_list)
    if not has_prime_in_a:
        return 0

    # Slide window over data
    for i in range(n - m + 1):
        # Check if the window matches a_list
        match = True
        for j in range(m):
            if data[i + j] != a_list[j]:
                match = False
                break
        if not match:
            continue

        # Check if the window contains at least one prime
        has_prime = False
        for j in range(m):
            if is_prime(data[i + j]):
                has_prime = True
                break
        if has_prime:
            count += 1

    return count
