def rotate_words(words, n):
    if not words:
        return []

    length = len(words)
    if n == 0:
        return words[:]

    # Normalize n to be within [0, length)
    if n > 0:
        n = n % length
    else:
        n = (n % length + length) % length

    # Build the rotated list without slicing or concatenation
    result = []
    start_index = n

    for _ in range(length):
        result.append(words[start_index])
        start_index = (start_index + 1) % length

