    def get_type_name(obj):
        return type(obj).__name__

    def traverse(obj):
        if isinstance(obj, dict):
            for value in obj.values():
                traverse(value)
        elif isinstance(obj, (list, tuple)):
            for item in obj:
                traverse(item)
        else:
            type_name = get_type_name(obj)
