def propagate_property(grid, key, initial_value, propagation_rules):
    if not grid:
        return grid

    # Get the propagation function for the given key, default to identity if not found
    rule = propagation_rules.get(key, lambda x: x)

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    for i in range(rows):
        for j in range(cols):
            if i == 0:
                # First row: use initial_value
                grid[i][j][key] = initial_value
            else:
                # Subsequent rows: propagate from the cell above
                value_above = grid[i - 1][j][key]
                grid[i][j][key] = rule(value_above)

