def longest_common_substring(s1, s2):
    n, m = len(s1), len(s2)
    if n == 0 or m == 0:
        return ""

    # dp[i][j] = length of longest common suffix of s1[:i] and s2[:j]
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    best_len = 0
    best_end = 0  # ending index in s1 (exclusive)

    for i in range(1, n + 1):
        for j in range(1, m + 1):
            if s1[i - 1] == s2[j - 1]:
                dp[i][j] = dp[i - 1][j - 1] + 1
                if dp[i][j] > best_len:
                    best_len = dp[i][j]
                    best_end = i
            else:
                dp[i][j] = 0

    return s1[best_end - best_len:best_end]
