def are_equal_deep(a, b):
    # If both are lists or both are tuples, treat them as equivalent sequences
    if type(a) == type(b):
        if not isinstance(a, (list, tuple)):
            return a == b
        if len(a) != len(b):
            return False
        for x, y in zip(a, b):
            if not are_equal_deep(x, y):
                return False
        return True
    else:
        # Different container types (e.g., list vs tuple) are considered equivalent
        # but if one is a container and the other is not, they are not equal
        if isinstance(a, (list, tuple)) or isinstance(b, (list, tuple)):
            return False
        return a == b
