import re

def convert_keys_to_snake_case(obj):
    """
    Recursively converts all dictionary keys to snake_case.
    - Strings are converted to lowercase with underscores separating words.
    - Lists and dicts are processed recursively.
    - Other types (int, float, bool, None) are returned unchanged.
    """

    def to_snake_case(s):
        # Insert underscore before uppercase letters that follow a lowercase letter or digit
        s = re.sub(r'([a-z0-9])([A-Z])', r'\1_\2', s)
        # Insert underscore before uppercase letters that are followed by lowercase letters
        # This handles cases like "XMLParser" -> "xml_parser"
        s = re.sub(r'([A-Z]+)([A-Z][a-z])', r'\1_\2', s)
        return s.lower()

    if isinstance(obj, dict):
        return {
            to_snake_case(k) if isinstance(k, str) else k: convert_keys_to_snake_case(v)
            for k, v in obj.items()
        }
    elif isinstance(obj, list):
        return [convert_keys_to_snake_case(item) for item in obj]
    else:
        return obj
```

