```python
def detect_cycles(graph):
    """
    Detects if a directed graph contains any cycle using DFS with three states:
    0 = unvisited, 1 = visiting (in current recursion stack), 2 = visited.

    :param graph: dict mapping node -> list of neighbor nodes
    :return: True if a cycle exists, False otherwise
    """
    # Initialize state for all nodes present in the graph
    # We use a set to track all nodes since some may not be keys if they have no outgoing edges
    all_nodes = set(graph.keys())
    for neighbors in graph.values():
        all_nodes.update(neighbors)

    state = {node: 0 for node in all_nodes}  # 0: unvisited, 1: visiting, 2: visited

    def dfs(node):
        if state[node] == 1:
            return True  # Back edge found -> cycle
        if state[node] == 2:
            return False  # Already fully processed

        state[node] = 1  # Mark as visiting

        for neighbor in graph.get(node, []):
            if dfs(neighbor):
                return True

        state[node] = 2  # Mark as visited
        return False

    # Run DFS from every unvisited node to handle disconnected components
    for node in all_nodes:
        if state[node] == 0:
            if dfs(node):
                return True

    return False
```

