def numTrees(n):
    memo = {}

    def count_trees(m):
        if m <= 1:
            return 1
        if m in memo:
            return memo[m]

        total = 0
        for root in range(1, m + 1):
            left_count = count_trees(root - 1)
            right_count = count_trees(m - root)
            total += left_count * right_count

        memo[m] = total
        return total

    return count_trees(n)
