        return 0

    total = 0
    current = ""
    i = 0
    n = len(string)

    while i < n:
        ch = string[i]
        if ch == separator:
            if current:
                try:
                    total += int(current)
                except ValueError:
                    pass
                current = ""
            i += 1
        elif ch.isdigit() or ch == '-':
            if ch == '-' and current and current[0] != '-':
                # This case shouldn't happen with valid logic, but guard against malformed starts
                pass
            current += ch
            i += 1
        else:
            # Non-digit, non-minus, non-separator: ignore and reset if we were building a number
            if current and (current[0] == '-' or current[1:].isdigit()):
                # We were in the middle of a number, but hit an invalid char
                try:
                    total += int(current)
                except ValueError:
                    pass
                current = ""
            i += 1

    # Process the last chunk if it's a valid integer
    if current:
        try:
            total += int(current)
        except ValueError:
            pass

    return total
