def coordinate_generator(coord_range):
    import re

    # Pattern to match optional ranges for x and y
    # Each part can be:
    # - a single number: (1, 2)
    # - a range: (1:3, 2:4)
    # We allow spaces around commas and colons
    pattern = r'^\s*\(\s*([^,)]+)\s*,\s*([^)]+)\s*\)$'
    match = re.match(pattern, coord_range.strip())

    if not match:
        raise ValueError("Invalid coordinate range format. Expected format: (x_range, y_range)")

    x_part, y_part = match.groups()

    def parse_range(part):
        if ':' in part:
            start_str, end_str = part.split(':')
            start = int(start_str.strip())
            end = int(end_str.strip())
            # Ensure start <= end by swapping if necessary
            if start > end:
                start, end = end, start
            return list(range(start, end + 1))
        else:
            val = int(part.strip())
            return [val]

    x_vals = parse_range(x_part)
    y_vals = parse_range(y_part)

    result = []
    for x in x_vals:
        for y in y_vals:
            result.append((x, y))

    return result
```

