def convert_to_postfix(infix_expr):
    precedence = {'+': 1, '-': 1, '*': 2, '/': 2}
    output = []
    stack = []

    for char in infix_expr:
        if char.isdigit():
            output.append(char)
        elif char in precedence:
            while (stack and stack[-1] in precedence and
                   precedence[stack[-1]] >= precedence[char]):
                output.append(stack.pop())
            stack.append(char)

    while stack:
        output.append(stack.pop())

    return ''.join(output)
```

