class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def findPath(rootNode):
    if rootNode is None:
        return []

    visited = []
    stack = [rootNode]

    while stack:
        node = stack[-1]
        if node.left is not None:
            stack.append(node.left)
        else:
            # No left child: visit current node
            visited.append(node.val)
            # Pop current node
            stack.pop()
            # If there's a right child, push it to explore next
            if node.right is not None:
                stack.append(node.right)
            else:
                # No right child: backtrack by popping until we find a node with a right child
                while stack and stack[-1].right is None:
                    stack.pop()
                # After popping, the new top (if exists) will have its right child pushed in next iteration
                # If stack is empty, we are done

    return visited
```

