def primes_in_range(a, b):
    """
    Returns a list of all prime numbers in the inclusive range [a, b].
    Handles edge cases:
      - If a > b: returns an empty list.
      - If b < 2: returns an empty list (no primes below 2).
    """
    if a > b or b < 2:
        return []

    # Ensure we start from at least 2
    start = max(a, 2)

    def is_prime(n):
        if n < 2:
            return False
        if n == 2:
            return True
        if n % 2 == 0:
            return False
        limit = int(n ** 0.5) + 1
        for i in range(3, limit, 2):
            if n % i == 0:
                return False
        return True

    return [n for n in range(start, b + 1) if is_prime(n)]
```

