def binary_search_recursive(lst, n):
    def helper(low, high, direction):
        # direction: 1 for left-first, -1 for right-first
        if low > high:
            return False

        mid = (low + high) // 2

        if lst[mid] == n:
            return True

        if lst[mid] < n:
            # Target is in the right half
            if direction == 1:
                # We came from a left-first path, now go right
                return helper(mid + 1, high, -1)
            else:
                # We came from a right-first path, but target is still right
                # Continue right but flip direction for next step
                return helper(mid + 1, high, 1)
        else:
            # Target is in the left half
            if direction == -1:
                # We came from a right-first path, now go left
                return helper(low, mid - 1, 1)
            else:
                # We came from a left-first path, but target is still left
                # Continue left but flip direction for next step
                return helper(low, mid - 1, -1)

    # Start with left-first direction
    return helper(0, len(lst) - 1, 1)
