def evaluate_postfix(expression: str) -> int:
    stack = Stack()
    tokens = expression.split()

    for token in tokens:
        if token in "+-*/":
            if stack.is_empty():
                raise ValueError("Invalid expression: not enough operands")
            right = stack.pop()
            if stack.is_empty():
                raise ValueError("Invalid expression: not enough operands")
            left = stack.pop()

            if token == "+":
                result = left + right
            elif token == "-":
                result = left - right
            elif token == "*":
                result = left * right
            elif token == "/":
                # Integer division as per typical postfix evaluator behavior
                result = int(left / right)
            else:
                raise ValueError(f"Unsupported operator: {token}")

            stack.push(result)
        else:
            # Assume token is an integer
            stack.push(int(token))

    if not stack.is_empty():
        return stack.pop()
    raise ValueError("Invalid expression: extra operands")
