    Recursively processes a nested dictionary, setting all integer values to 0.
    Returns a deep copy of the dictionary with modified values.

    Args:
        element_table (dict): A dictionary where values are either integers or nested dictionaries.

    Returns:
        dict: A new dictionary with the same structure, but all integer values set to 0.
    """
    if not isinstance(element_table, dict):
        return element_table

    new_dict = {}
    for key, value in element_table.items():
        if isinstance(value, int):
            new_dict[key] = 0
        elif isinstance(value, dict):
            new_dict[key] = initialize_element_states(value)
        else:
            # Preserve other types as-is (e.g., lists, strings, etc.)
            new_dict[key] = value

    return new_dict
