import json
import os

def calculate_average(json_data):
    """
    Calculates the average of all numeric values in a JSON structure.

    Parameters:
    json_data (dict or list): The parsed JSON data

    Returns:
    float: The average of all numeric values, or None if no numeric values are found
    """
    def extract_numbers(data):
        numbers = []
        if isinstance(data, dict):
            for value in data.values():
                numbers.extend(extract_numbers(value))
        elif isinstance(data, list):
            for item in data:
                numbers.extend(extract_numbers(item))
        elif isinstance(data, (int, float)) and not isinstance(data, bool):
            numbers.append(data)
        return numbers

    try:
        if isinstance(json_data, str):
            json_data = json.loads(json_data)

        numbers = extract_numbers(json_data)

        if not numbers:
            return None

        return sum(numbers) / len(numbers)

    except FileNotFoundError:
        print("Error: File not found.")
        return None
    except json.JSONDecodeError:
        print("Error: Invalid JSON format.")
        return None
    except Exception as e:
        print(f"Error: {str(e)}")
