class TreeNode:
    def __init__(self, val=0, left=None, right=None):
        self.val = val
        self.left = left
        self.right = right

def roman_to_int(s: str) -> int:
    roman_map = {
        'I': 1,
        'V': 5,
        'X': 10,
        'L': 50,
        'C': 100,
        'D': 500,
        'M': 1000
    }
    total = 0
    i = 0
    while i < len(s):
        val = roman_map[s[i]]
        if i + 1 < len(s) and val < roman_map[s[i + 1]]:
            total += roman_map[s[i + 1]] - val
            i += 2
        else:
            total += val
            i += 1
    return total

def insert_into_bst(root: TreeNode, val: int) -> TreeNode:
    if root is None:
        return TreeNode(val)
    if val < root.val:
        root.left = insert_into_bst(root.left, val)
    elif val > root.val:
        root.right = insert_into_bst(root.right, val)
    # If equal, do not insert (to keep distinct values only)
    return root

def count_distinct_integers(roman_sequences):
    root = None
    for seq in roman_sequences:
        num = roman_to_int(seq)
        root = insert_into_bst(root, num)

    # Count distinct nodes in BST
    count = 0
    stack = [root]
    while stack:
        node = stack.pop()
        if node:
            count += 1
            stack.append(node.left)
            stack.append(node.right)
    return count
```

