def product_except_self(nums):
    n = len(nums)
    zero_count = nums.count(0)

    if zero_count > 1:
        return [0] * n

    result = [1] * n

    # Compute prefix products
    prefix = 1
    for i in range(n):
        if i != 0:
            result[i] = prefix
        prefix *= nums[i]

    # Compute suffix products and handle zeros
    suffix = 1
    for i in range(n - 1, -1, -1):
        if i != n - 1:
            result[i] *= suffix
        suffix *= nums[i]

    # If there is exactly one zero, only the position of zero gets the total product of others
    if zero_count == 1:
        zero_index = nums.index(0)
        total_product = 1
        for x in nums:
            if x != 0:
                total_product *= x
        result[zero_index] = total_product

    return result
