def vector_difference(vector1, vector2):
    if isinstance(vector1, list):
        # Both are lists
        return [v1 - v2 for v1, v2 in zip(vector1, vector2)]
    else:
        # Both are dictionaries (sparse vectors)
        result = {}
        all_keys = set(vector1.keys()) | set(vector2.keys())
        for key in all_keys:
            val1 = vector1.get(key, 0)
            val2 = vector2.get(key, 0)
            diff = val1 - val2
            if diff != 0:
                result[key] = diff
        return result
```

