        if isinstance(name, list):
            return '-'.join(str(part) for part in name)
        return str(name)

    first = format_component(first_name)
    last = format_component(last_name)
    middle = format_component(middle_name) if middle_name else ''

    if middle:
        return f"{first.title()} {middle.title()} {last.title()}"
    return f"{first.title()} {last.title()}"
