def remove_tags(s: str) -> str:
    result = []
    i = 0
    n = len(s)
    while i < n:
        if s[i] == '<':
            # Skip until the closing '>'
            while i < n and s[i] != '>':
                i += 1
            if i < n:
                i += 1  # Move past '>'
        else:
            result.append(s[i])
            i += 1
    return ''.join(result)
