import inspect

def count_fixed_parameters(callable):
    sig = inspect.signature(callable)
    count = 0
    for name, param in sig.parameters.items():
        if param.kind in (
            inspect.Parameter.POSITIONAL_ONLY,
            inspect.Parameter.POSITIONAL_OR_KEYWORD
        ):
            if param.default is inspect.Parameter.empty:
                # Exclude *args and **kwargs (POSITIONAL_VARARGS, KEYWORD_VARARGS)
                # and also exclude parameters that are dictionaries or tuples
                if not (
                    isinstance(param.default, dict) or
                    isinstance(param.default, tuple)
                ):
                    count += 1
    return count
```

